// app/todos/actions.ts —— Server Action（服务端）
'use server';

import { revalidatePath } from 'next/cache';
import { db } from '@/lib/db';

export type Todo = { id: string; text: string; done: boolean };
export type TodoState = { todos: Todo[]; error?: string };

export async function addTodo(
  prevState: TodoState,
  formData: FormData
): Promise<TodoState> {
  const text = String(formData.get('text') ?? '').trim();
  if (!text) return { ...prevState, error: '内容不能为空' };

  // 1. 持久化：返回真实 id，用于替换乐观临时 id
  const created = await db.todo.create({ data: { text, done: false } });

  // 2. 让服务端组件重新渲染，带上最新数据
  revalidatePath('/todos');

  // 3. 返回完整新状态，useActionState 会用它替换乐观状态
  return {
    todos: [...prevState.todos, { id: created.id, text, done: false }],
  };
}

// app/todos/todo-form.tsx —— 客户端交互薄壳
'use client';

import { useActionState, useOptimistic, useRef, useState } from 'react';
import { addTodo, type Todo, type TodoState } from './actions';

export function TodoForm({ initialTodos }: { initialTodos: Todo[] }) {
  const [state, formAction, isPending] = useActionState<TodoState, FormData>(
    addTodo,
    { todos: initialTodos }
  );

  // 乐观状态：真实 state 更新后，未落地的补丁会被自动丢弃
  const [optimisticTodos, addOptimistic] = useOptimistic(
    state.todos,
    (current: Todo[], newTodo: Todo) => {
      // 用 id 做 upsert，保证并发提交不产生重复条目
      const exists = current.some((t) => t.id === newTodo.id);
      return exists
        ? current.map((t) => (t.id === newTodo.id ? newTodo : t))
        : [...current, newTodo];
    }
  );

  const formRef = useRef<HTMLFormElement>(null);

  return (
    <div>
      <form
        ref={formRef}
        action={async (formData) => {
          const text = String(formData.get('text') ?? '').trim();
          if (!text) return;

          // 立刻写入乐观补丁，UI 零延迟反馈
          addOptimistic({ id: `temp-${Date.now()}`, text, done: false });
          formRef.current?.reset();
          await formAction(formData);
        }}
      >
        <input name="text" placeholder="新待办..." disabled={isPending} />
        <button type="submit" disabled={isPending}>
          {isPending ? '提交中…' : '添加'}
        </button>
      </form>

      {state.error && <p role="alert">{state.error}</p>}

      <ul>
        {optimisticTodos.map((todo) => (
          <li key={todo.id} style={{ opacity: todo.id.startsWith('temp-') ? 0.6 : 1 }}>
            {todo.text}
          </li>
        ))}
      </ul>
    </div>
  );
}

// app/todos/page.tsx —— Server Component 负责权威数据
import { db } from '@/lib/db';
import { TodoForm } from './todo-form';

export default async function TodosPage() {
  const todos = await db.todo.findMany({ orderBy: { createdAt: 'desc' } });
  return <TodoForm initialTodos={todos} />;
}

